/** Select the exact source facts shown to the shopper, not just the ID.
 * Replacing an original SKU, physical amount, package, captured time or line
 * price between render and click must invalidate the pending local export.
 * Both arguments are generated by the existing admitted-price renderer.
 */
export function selectOriginalPricePairs<T extends { ingredientId: string }>(
  admitted: readonly T[],
  renderedSelection?: readonly T[],
): T[] {
  if (!renderedSelection) return [...admitted]
  if (!Array.isArray(renderedSelection) || renderedSelection.length === 0 ||
      renderedSelection.length > 1000) {
    throw new Error('Er zijn geen geldige geselecteerde winkelprijsregels.')
  }
  const byId = new Map(admitted.map(pair => [pair.ingredientId, pair]))
  if (byId.size !== admitted.length)
    throw new Error('De oorspronkelijke prijsvergelijking bevat dubbele ingrediënten.')
  const selectedIds = new Set<string>()
  return renderedSelection.map(expected => {
    if (!expected || typeof expected.ingredientId !== 'string' ||
        !expected.ingredientId || selectedIds.has(expected.ingredientId)) {
      throw new Error('De productselectie bevat dubbele of ontbrekende ingrediënten.')
    }
    selectedIds.add(expected.ingredientId)
    const current = byId.get(expected.ingredientId)
    // Same ingredient ID is NOT enough to authorize a different source/SKU.
    // All canonical paired price details are primitive own-source snapshots,
    // built deterministically by privateKnownPricePairs.
    if (!current || JSON.stringify(current) !== JSON.stringify(expected))
      throw new Error('Een gekozen winkelprijs, originele SKU of bronmoment is gewijzigd. Selecteer opnieuw.')
    return current
  })
}
